SourceCode.Declaration:
/// <summary>
/// Updates supplying warehouse for selected METSalesLine records.
/// Called from a menu item button with MultiSelect = Yes.
/// </summary>
class METUpdateSupplyingWarehouse
{
    METSalesLine     metSalesLine;
    Dialog           dialogWarehouse;
    DialogField      dialogFieldWarehouseId;
    InventLocationId newWarehouseId;

}

Method.Source:
/// <summary>
/// Gets or sets the METSalesLine record.
/// </summary>
/// <param name="_metSalesLine">METSalesLine record.</param>
/// <returns>METSalesLine record.</returns>
public METSalesLine parmMETSalesLine(METSalesLine _metSalesLine = metSalesLine)
{
    metSalesLine = _metSalesLine;
    return metSalesLine;
}

/// <summary>
/// Constructs a new instance of <c>METUpdateSupplyingWarehouse</c>.
/// </summary>
/// <returns>New instance of <c>METUpdateSupplyingWarehouse</c>.</returns>
public static METUpdateSupplyingWarehouse construct()
{
    return new METUpdateSupplyingWarehouse();
}

/// <summary>
/// Entry point when called from a menu item button.
/// </summary>
/// <param name="_args">Args object containing METSalesLine record and datasource context.</param>
public static void main(Args _args)
{
    if (!_args || !_args.record() || _args.record().TableId != tableNum(METSalesLine))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    FormRun formRun = _args.caller();
    FormDataSource dsMETSalesLine = formRun.dataSource(formDataSourceStr(SalesTable, METSalesLine));

    // If dsMETSalesLine is not available, fallback to current cursor record
    if (!dsMETSalesLine)
    {
        dsMETSalesLine = formRun.dataSource(tableStr(METSalesLine));
    }

    METUpdateSupplyingWarehouse updateWarehouse = METUpdateSupplyingWarehouse::construct();
    updateWarehouse.run(dsMETSalesLine);

    FormDataSource dsMETSalesTable = formRun.dataSource(tableStr(SalesTable));

    dsMETSalesTable.research(true);
    dsMETSalesTable.refresh();
}

/// <summary>
/// Executes the process: shows dialog, validates, confirms, and updates selected lines.
/// </summary>
/// <param name="_dsMETSalesLine">METSalesLine datasource containing selected records.</param>
public void run(FormDataSource _dsMETSalesLine)
{
    this.initDialog();
    dialogWarehouse.run();

    if (dialogWarehouse.closedOk())
    {
        newWarehouseId = dialogFieldWarehouseId.value();

        if (!InventLocation::find(newWarehouseId))
        {
            warning("@MET:UpdateSupplyingWarehouseInvalidMsg");
            return;
        }

        if (this.validate(_dsMETSalesLine))
        {
            if (Box::yesNo("@MET:UpdateSupplyingWarehouseConfirmMsg", DialogButton::No) == DialogButton::Yes)
            {
                this.updateLines(_dsMETSalesLine);
            }
        }
    }
}

/// <summary>
/// Initializes the warehouse selection dialog.
/// </summary>
private void initDialog()
{
    dialogWarehouse = new Dialog("@MET:UpdateSupplyingWarehouseButton");
    dialogFieldWarehouseId = dialogWarehouse.addFieldValue(extendedTypeStr(InventLocationId), '');
}

/// <summary>
/// Validates that all selected lines have the same supplying warehouse or blank.
/// </summary>
/// <param name="_dsMETSalesLine">METSalesLine datasource containing selected records.</param>
/// <returns>True if valid; otherwise, false.</returns>
private boolean validate(FormDataSource _dsMETSalesLine)
{
    METSalesLine line = _dsMETSalesLine.getFirst(true);
    InventLocationId firstWarehouseId;
    boolean ret = true;

    while (line)
    {
        if (!firstWarehouseId && line.SupplyingWarehouse)
        {
            // First non-blank warehouse encountered
            firstWarehouseId = line.SupplyingWarehouse;
        }
        else if (line.SupplyingWarehouse && firstWarehouseId && line.SupplyingWarehouse != firstWarehouseId)
        {
            // Found a different non-blank warehouse
            ret = checkFailed("@MET:UpdateSupplyingWarehouseValidationMsg");
            break;
        }

        line = _dsMETSalesLine.getNext();
    }

    return ret;
}

/// <summary>
/// Updates supplying warehouse for all selected METSalesLine records.
/// </summary>
/// <param name="_dsMETSalesLine">METSalesLine datasource containing selected records.</param>
private void updateLines(FormDataSource _dsMETSalesLine)
{
    METSalesLine line = _dsMETSalesLine.getFirst(true);

    ttsBegin;
    while (line)
    {
        if (line.SupplyingWarehouse != newWarehouseId)
        {
            line.SupplyingWarehouse = newWarehouseId;
            line.update();
        }

        line = _dsMETSalesLine.getNext();
    }
    ttsCommit;
}
